260→// runCleanAll cleans all orphaned data across the repository (old `entire clean` behavior).
261→func runCleanAll(ctx context.Context, cmd *cobra.Command, force, dryRun bool) error {
262→	// List all cleanup items
263→	items, err := strategy.ListAllCleanupItems(ctx)
264→	if err != nil {
265→		return fmt.Errorf("failed to list orphaned items: %w", err)
266→	}
267→
268→	// List temp files
269→	tempFiles, err := listTempFiles(ctx)
